            {
                // Ignore text that is not a #RRGGBB colour (typing in progress); the last valid colour stays.
                if (value == null || !HexColour.IsMatch(value))
                {
                    return;
                }

                value = value.ToUpperInvariant();
                if (_fxScDeltaOkColour != value)
                {
                    _fxScDeltaOkColour = value;
                    Raise("FxScDeltaOkColour");
                }
            }
        }

