        /// <summary>Restores one setting to its default; false when the name is not a setting.</summary>
        public bool ResetSetting(string name)
        {
            switch (name)
            {
                case "SideLeds":
                    SideLeds = 5;
                    return true;
                case "CentreLeds":
                    CentreLeds = 16;
                    return true;
                case "LedFunction":
                    LedFunction = "rpmBrake";
                    return true;
                case "BrightnessGeneral":
                    BrightnessGeneral = 100;
                    return true;
                case "NightMode":
                    NightMode = false;
                    return true;
                case "BrightnessIdle":
                    BrightnessIdle = 40;
                    return true;
                case "RpmStyle":
                    RpmStyle = "middle";
                    return true;
                case "RpmThemeId":
