                case "RpmStartPercent":
                    RpmStartPercent = 70;
                    return true;
                case "RpmEndPercent":
                    RpmEndPercent = 97;
                    return true;
                case "RpmRedline":
                    RpmRedline = "flash";
                    return true;
                case "RpmShiftFlash":
                    RpmShiftFlash = false;
                    return true;
                case "RpmNoFlashInTopGear":
                    RpmNoFlashInTopGear = true;
                    return true;
                case "RpmFlashColour":
                    RpmFlashColour = "#FF0000";
                    return true;
                case "RpmFlashColour2":
